{
  "name": "@a-r-m-i-n/opencode-openai-usage",
  "version": "0.1.5",
  "description": "OpenCode plugin that shows ChatGPT/OpenAI usage in the sidebar and command palette.",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/a-r-m-i-n/opencode-openai-usage.git"
  },
  "homepage": "https://github.com/a-r-m-i-n/opencode-openai-usage#readme",
  "bugs": {
    "url": "https://github.com/a-r-m-i-n/opencode-openai-usage/issues"
  },
  "type": "module",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "openai",
    "chatgpt",
    "tui"
  ],
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    ".": "./dist/index.js",
    "./tui": "./dist/tui.js"
  },
  "scripts": {
    "build": "tsup",
    "test": "node --import tsx --test ./src/lib/openai-usage.test.ts",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.15.10"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.2.15",
    "@opentui/solid": ">=0.2.15",
    "solid-js": "1.9.12"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "esbuild-plugin-solid": "^0.6.0",
    "@opentui/core": "0.2.16",
    "@opentui/solid": "0.2.16",
    "solid-js": "1.9.12",
    "tsup": "^8.3.6",
    "tsx": "^4.19.2",
    "typescript": "^5.8.3"
  }
}
